#!/bin/bash
# Renomeia os artigos de "5 Estudos" e "1 TCC/Referências" para o formato
#   Autor (Ano) - Título curto em português.pdf
# (tradução marcada com [tradução]; só o primeiro autor; fonte quando não há autor)
#
# - Os arquivos NÃO mudam de pasta, só de nome.
# - Mostra o plano antes (abre no TextEdit) e só aplica se você confirmar.
# - Nunca apaga nem sobrescreve (se o nome já existir, ganha " (2)").
# - Cria um script para DESFAZER tudo.
#
# Como usar (no Terminal):  bash ~/Downloads/renomear_artigos_pt.sh
# VERSAO 1

case "${LC_ALL:-${LC_CTYPE:-$LANG}}" in *UTF-8*|*utf8*) ;; *) export LC_ALL=en_US.UTF-8 ;; esac

DATA="$(date +%Y-%m-%d_%H-%M-%S)"
PLANO="$HOME/Downloads/PLANO_nomes_artigos_$DATA.txt"
DESFAZER="$HOME/Downloads/DESFAZER_nomes_artigos_$DATA.sh"
TMPD="$(mktemp -d)"
trap 'rm -rf "$TMPD"' EXIT

livre() {   # caminho -> caminho que ainda não existe
  local p="$1" k=2 base ext
  [ -e "$p" ] || { echo "$p"; return; }
  base="${p%.*}"; ext=".${p##*.}"
  while [ -e "$base ($k)$ext" ]; do k=$((k + 1)); done
  echo "$base ($k)$ext"
}

sed -n "/^: <<'__LISTA__'$/,/^__LISTA__$/p" "$0" | sed '1d;$d' > "$TMPD/lista"

SRC=(); DST=(); faltando=0
while IFS=$'\t' read -r src dst; do
  [ -z "$src" ] && continue
  if [ ! -e "$HOME/$src" ]; then faltando=$((faltando + 1)); echo "$src" >> "$TMPD/faltando"; continue; fi
  SRC+=("$src"); DST+=("$dst")
done < "$TMPD/lista"

# ---------- Plano ----------
{
  echo "PLANO: NOMES DOS ARTIGOS EM PORTUGUÊS — $DATA"
  echo "Nada foi mudado ainda. Volte ao Terminal para confirmar."
  echo "Formato:  NOME NOVO"
  echo "              era: nome atual"
  echo "(agrupado por pasta; os arquivos continuam na mesma pasta)"
  i=0
  while [ $i -lt ${#SRC[@]} ]; do
    d="${SRC[$i]%/*}"; d="${d#Documents/}"
    printf '%s\t%s\t%s\n' "$d" "${DST[$i]##*/}" "${SRC[$i]##*/}"
    i=$((i + 1))
  done | sort -t$'\t' -k1,1 -k2,2 | awk -F'\t' '$1!=g{g=$1; print "\n\n=== " g " ==="} {print "\n   " $2 "\n              era: " $3}'
  if [ $faltando -gt 0 ]; then echo; echo "=== NÃO ENCONTRADOS (serão ignorados) ==="; cat "$TMPD/faltando"; fi
} > "$PLANO"

echo
echo "Arquivos a renomear: ${#SRC[@]}"
[ $faltando -gt 0 ] && echo "Não encontrados (serão ignorados): $faltando"
echo "Por pasta:"
i=0; while [ $i -lt ${#SRC[@]} ]; do d="${SRC[$i]%/*}"; echo "${d#Documents/}"; i=$((i + 1)); done | sort | uniq -c
echo
echo "O plano completo está em: $PLANO"
open -e "$PLANO" 2>/dev/null
printf "Aplicar? (s = sim / n = não) "
read -r ok
if [ "$ok" != "s" ] && [ "$ok" != "S" ]; then echo "Cancelado. Nada foi alterado."; exit 0; fi

# ---------- Aplica (o desfazer volta na ordem inversa) ----------
PASSOS="$TMPD/passos"; : > "$PASSOS"
gerar_desfazer() {
  { echo "#!/bin/bash"; echo "# Desfaz a renomeação dos artigos feita em $DATA"
    awk '{a[NR]=$0} END{for(i=NR;i>=1;i--) print a[i]}' "$PASSOS"; } > "$DESFAZER"
}
trap 'gerar_desfazer; rm -rf "$TMPD"' EXIT

feitos=0; erros=0
i=0
while [ $i -lt ${#SRC[@]} ]; do
  src="$HOME/${SRC[$i]}"; dst="$HOME/${DST[$i]}"
  i=$((i + 1))
  [ -e "$src" ] || continue
  if [ -e "$dst" ] && [ "$src" -ef "$dst" ]; then   # só muda maiúsculas/acentos: renomeia em 2 passos
    tmp="$src.renomeando$$"
    if mv -n "$src" "$tmp" && mv -n "$tmp" "$dst"; then
      printf 'mv -n %q %q && mv -n %q %q\n' "$dst" "$tmp" "$tmp" "$src" >> "$PASSOS"
      feitos=$((feitos + 1))
    else
      erros=$((erros + 1))
    fi
    continue
  fi
  alvo="$(livre "$dst")"
  if mv -n "$src" "$alvo"; then
    printf 'mv -n %q %q\n' "$alvo" "$src" >> "$PASSOS"
    feitos=$((feitos + 1))
  else
    erros=$((erros + 1))
  fi
done

echo
echo "Pronto! $feitos artigos renomeados."
[ $erros -gt 0 ] && echo "Atenção: $erros não puderam ser renomeados (veja as mensagens acima)."
echo "Para desfazer:"
echo "  bash \"$DESFAZER\""
open "$HOME/Documents/5 Estudos" 2>/dev/null
exit 0

